import math
import itertools
import pytest
from hypothesis import given, assume
from hypothesis import strategies as st

from solution import triangle_area


def reference(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    prod = s * (s - a) * (s - b) * (s - c)
    # guard tiny negative due to floating point on degenerate inputs
    if prod < 0 and prod > -1e-12:
        prod = 0.0
    return round(math.sqrt(prod), 2)


def test_spec_example_3_4_5():
    assert triangle_area(3, 4, 5) == 6.00


def test_spec_example_1_2_10():
    assert triangle_area(1, 2, 10) == -1


def test_degenerate_equality_returns_minus_one():
    # sum of two equals third is NOT valid (needs strictly greater)
    assert triangle_area(1, 2, 3) == -1
    assert triangle_area(2, 3, 5) == -1
    assert triangle_area(3, 1, 2) == -1
    assert triangle_area(2, 1, 3) == -1
    assert triangle_area(5, 5, 10) == -1
    assert triangle_area(5, 10, 5) == -1
    assert triangle_area(10, 5, 5) == -1


def test_degenerate_zero_area_is_invalid():
    # the buggy `b + c < a` vs `<=` case: b+c == a must be -1, not 0.0
    assert triangle_area(10, 5, 5) == -1
    assert triangle_area(7, 3, 4) == -1
    assert triangle_area(100, 60, 40) == -1


def test_just_below_degenerate_is_invalid():
    assert triangle_area(1, 2, 3.0000001) == -1
    assert triangle_area(10, 5, 5.0001) == -1
    assert triangle_area(10, 5.0001, 5) == -1


def test_nonpositive_sides_are_invalid():
    assert triangle_area(0, 0, 0) == -1
    assert triangle_area(0, 1, 1) == -1
    assert triangle_area(-1, 2, 2) == -1
    assert triangle_area(3, 4, -5) == -1
    assert triangle_area(-3, -4, -5) == -1


@given(
    a=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_validity_condition_matches_spec(a, b, c):
    valid = (a + b > c) and (a + c > b) and (b + c > a)
    result = triangle_area(a, b, c)
    if not valid:
        assert result == -1
    else:
        assert result != -1
        assert result >= 0


@given(
    a=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=-10, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_matches_heron_reference_model(a, b, c):
    assert triangle_area(a, b, c) == reference(a, b, c)


@given(
    a=st.integers(min_value=1, max_value=20),
    b=st.integers(min_value=1, max_value=20),
    c=st.integers(min_value=1, max_value=20),
)
def test_integer_triples_match_reference(a, b, c):
    assert triangle_area(a, b, c) == reference(a, b, c)


@given(
    a=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_permutation_invariance(a, b, c):
    assume(a + b > c and a + c > b and b + c > a)
    results = {triangle_area(x, y, z) for x, y, z in itertools.permutations((a, b, c))}
    assert len(results) == 1
    # also invalid triples are permutation invariant
@given(
    a=st.floats(min_value=-5, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=-5, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=-5, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_permutation_invariance_general(a, b, c):
    r0 = triangle_area(a, b, c)
    for x, y, z in itertools.permutations((a, b, c)):
        assert triangle_area(x, y, z) == r0


@given(
    a=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
    b=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
    c=st.floats(min_value=0.1, max_value=10, allow_nan=False, allow_infinity=False),
)
def test_valid_result_is_rounded_to_2_decimals(a, b, c):
    assume(a + b > c and a + c > b and b + c > a)
    result = triangle_area(a, b, c)
    assert result == round(result, 2)
    assert result == pytest.approx(reference(a, b, c))


def test_known_values():
    assert triangle_area(2, 2, 3) == reference(2, 2, 3) == 1.98
    assert triangle_area(5, 5, 5) == reference(5, 5, 5) == 10.83
    assert triangle_area(6, 8, 10) == 24.0
    assert triangle_area(10, 10, 10) == reference(10, 10, 10)
    # scaling: (6,8,10) is 2x (3,4,5) so area 4x
    assert triangle_area(6, 8, 10) == 4 * triangle_area(3, 4, 5)


@given(x=st.floats(min_value=0.1, max_value=20, allow_nan=False, allow_infinity=False))
def test_equilateral_matches_closed_form(x):
    assume(x > 0)
    expected = round((math.sqrt(3) / 4) * x * x, 2)
    assert triangle_area(x, x, x) == pytest.approx(expected)
